#!/bin/sh
set -eu
PACKAGE_ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)
WORK_DIR=${EYE_BUILD_DIR:-"$PACKAGE_ROOT/build/work/ncnn"}
if [ -e "$WORK_DIR" ]; then echo "Choose a new EYE_BUILD_DIR" >&2; exit 1; fi
mkdir -p "$WORK_DIR"
cd "$WORK_DIR"
python3 -m zipfile -e "$PACKAGE_ROOT/data/third_party/ncnn-20261020.zip" ncnn-source
cmake -S ncnn-source/ncnn-20261020 -B ncnn-build -DCMAKE_BUILD_TYPE=Release -DCMAKE_CXX_FLAGS="-mcpu=cortex-a9 -mfpu=neon -mfloat-abi=hard" -DCMAKE_C_FLAGS="-mcpu=cortex-a9 -mfpu=neon -mfloat-abi=hard" -DNCNN_SHARED_LIB=OFF -DNCNN_BUILD_TOOLS=OFF -DNCNN_BUILD_EXAMPLES=OFF -DNCNN_BUILD_BENCHMARK=OFF -DNCNN_VULKAN=OFF -DNCNN_RUNTIME_CPU=OFF -DNCNN_VFPV4=OFF -DNCNN_INT8=OFF -DNCNN_BF16=OFF -DNCNN_WEIGHT_QUANT=OFF -DNCNN_BATCH=OFF -DNCNN_PIXEL=OFF -DWITH_LAYER_absval=OFF -DWITH_LAYER_argmax=OFF -DWITH_LAYER_batchnorm=OFF -DWITH_LAYER_bias=OFF -DWITH_LAYER_bnll=OFF -DWITH_LAYER_concat=OFF -DWITH_LAYER_crop=OFF -DWITH_LAYER_deconvolution=OFF -DWITH_LAYER_dropout=OFF -DWITH_LAYER_eltwise=OFF -DWITH_LAYER_elu=OFF -DWITH_LAYER_embed=OFF -DWITH_LAYER_exp=OFF -DWITH_LAYER_log=OFF -DWITH_LAYER_lrn=OFF -DWITH_LAYER_memorydata=OFF -DWITH_LAYER_mvn=OFF -DWITH_LAYER_power=OFF -DWITH_LAYER_prelu=OFF -DWITH_LAYER_proposal=OFF -DWITH_LAYER_reduction=OFF -DWITH_LAYER_roipooling=OFF -DWITH_LAYER_scale=OFF -DWITH_LAYER_slice=OFF -DWITH_LAYER_softmax=OFF -DWITH_LAYER_spp=OFF -DWITH_LAYER_tanh=OFF -DWITH_LAYER_threshold=OFF -DWITH_LAYER_tile=OFF -DWITH_LAYER_rnn=OFF -DWITH_LAYER_lstm=OFF -DWITH_LAYER_unaryop=OFF -DWITH_LAYER_squeeze=OFF -DWITH_LAYER_expanddims=OFF -DWITH_LAYER_normalize=OFF -DWITH_LAYER_permute=OFF -DWITH_LAYER_priorbox=OFF -DWITH_LAYER_detectionoutput=OFF -DWITH_LAYER_interp=OFF -DWITH_LAYER_deconvolutiondepthwise=OFF -DWITH_LAYER_shufflechannel=OFF -DWITH_LAYER_instancenorm=OFF -DWITH_LAYER_reorg=OFF -DWITH_LAYER_yolodetectionoutput=OFF -DWITH_LAYER_quantize=OFF -DWITH_LAYER_dequantize=OFF -DWITH_LAYER_yolov3detectionoutput=OFF -DWITH_LAYER_psroipooling=OFF -DWITH_LAYER_roialign=OFF -DWITH_LAYER_requantize=OFF -DWITH_LAYER_hardsigmoid=OFF -DWITH_LAYER_selu=OFF -DWITH_LAYER_hardswish=OFF -DWITH_LAYER_noop=OFF -DWITH_LAYER_pixelshuffle=OFF -DWITH_LAYER_deepcopy=OFF -DWITH_LAYER_mish=OFF -DWITH_LAYER_statisticspooling=OFF -DWITH_LAYER_swish=OFF -DWITH_LAYER_groupnorm=OFF -DWITH_LAYER_layernorm=OFF -DWITH_LAYER_softplus=OFF -DWITH_LAYER_gru=OFF -DWITH_LAYER_multiheadattention=OFF -DWITH_LAYER_gelu=OFF -DWITH_LAYER_convolution1d=OFF -DWITH_LAYER_pooling1d=OFF -DWITH_LAYER_convolutiondepthwise1d=OFF -DWITH_LAYER_convolution3d=OFF -DWITH_LAYER_convolutiondepthwise3d=OFF -DWITH_LAYER_pooling3d=OFF -DWITH_LAYER_matmul=OFF -DWITH_LAYER_deconvolution1d=OFF -DWITH_LAYER_deconvolutiondepthwise1d=OFF -DWITH_LAYER_deconvolution3d=OFF -DWITH_LAYER_deconvolutiondepthwise3d=OFF -DWITH_LAYER_einsum=OFF -DWITH_LAYER_deformableconv2d=OFF -DWITH_LAYER_glu=OFF -DWITH_LAYER_fold=OFF -DWITH_LAYER_unfold=OFF -DWITH_LAYER_gridsample=OFF -DWITH_LAYER_cumulativesum=OFF -DWITH_LAYER_copyto=OFF -DWITH_LAYER_erf=OFF -DWITH_LAYER_diag=OFF -DWITH_LAYER_celu=OFF -DWITH_LAYER_shrink=OFF -DWITH_LAYER_rmsnorm=OFF -DWITH_LAYER_spectrogram=OFF -DWITH_LAYER_inversespectrogram=OFF -DWITH_LAYER_flip=OFF -DWITH_LAYER_sdpa=OFF -DWITH_LAYER_rotaryembed=OFF
cmake --build ncnn-build -j1
printf 'NCNN_BUILD_OK\n'

g++ -std=c++11 -O3 -fPIC -shared -mcpu=cortex-a9 -mfpu=neon -mfloat-abi=hard -fopenmp -I ncnn-source/ncnn-20261020/src -I ncnn-build/src "$PACKAGE_ROOT/src/native/ncnn_bridge.cpp" ncnn-build/src/libncnn.a -pthread -o libgesture_ncnn.so
